using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

/// <summary>
/// Adds LODGroups to the heaviest Meshy environment props (10-30k triangles, hundreds of instances).
/// LOD0 stays the original mesh; LOD1/LOD2 are generated by UV-aware vertex clustering and saved under
/// Assets/Art/Meshy/Generated/EnvironmentLods. Prefabs are edited in place, so every scene instance inherits the LODs.
/// Safe to re-run: generated LOD children and the LODGroup are rebuilt each time.
/// </summary>
public static class MeshyEnvironmentLodBuilder
{
    private static readonly string[] Props =
    {
        "CayDaCoThu_LangViet", "DaNui_RungThieng", "DamSenCo_VanLang",
        "KhomTreNga_ThanThanh", "MoQuangSat_PhongChau", "CotMocDa_DongSon"
    };

    private const string FbxPattern = "Assets/Art/Meshy/Environment/{0}/{0}.fbx";
    private const string PrefabPattern = "Assets/Prefabs/Meshy/Environment/Meshy_{0}.prefab";
    private const string OutFolder = "Assets/Art/Meshy/Generated/EnvironmentLods";

    // Fractions of the original triangle count, and the screen-height thresholds where each LOD takes over.
    private const float Lod1Ratio = 0.45f, Lod2Ratio = 0.18f;
    private const float Lod0Screen = 0.22f, Lod1Screen = 0.09f, CullScreen = 0.015f;

    [MenuItem("Tools/Thanh Giong/Build Meshy Environment LODs")]
    public static void BuildMenu() { Debug.Log(Build()); }

    public static string Build()
    {
        var report = new StringBuilder("[MeshyEnvLOD]\n");
        Directory.CreateDirectory(OutFolder);
        foreach (string prop in Props)
        {
            try { report.AppendLine(BuildProp(prop)); }
            catch (System.Exception e) { report.AppendLine("FAIL " + prop + ": " + e.Message); }
        }
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        return report.ToString();
    }

    private static string BuildProp(string prop)
    {
        string fbx = string.Format(FbxPattern, prop);
        Mesh source = null;
        foreach (Object o in AssetDatabase.LoadAllAssetsAtPath(fbx))
            if (o is Mesh m && (source == null || m.vertexCount > source.vertexCount)) source = m;
        if (source == null) return "SKIP " + prop + ": no mesh in " + fbx;

        int srcTris = TriangleCount(source);
        Mesh lod1 = Save(Simplify(source, Lod1Ratio, prop + "_LOD1"), prop + "_LOD1");
        Mesh lod2 = Save(Simplify(source, Lod2Ratio, prop + "_LOD2"), prop + "_LOD2");

        string prefabPath = string.Format(PrefabPattern, prop);
        GameObject root = PrefabUtility.LoadPrefabContents(prefabPath);
        try
        {
            // Rebuild from scratch on re-run.
            foreach (var old in root.GetComponentsInChildren<LODGroup>(true)) Object.DestroyImmediate(old);
            foreach (var t in root.GetComponentsInChildren<Transform>(true))
                if (t != null && (t.name.EndsWith("_LOD1") || t.name.EndsWith("_LOD2"))) Object.DestroyImmediate(t.gameObject);

            MeshFilter lod0Filter = null;
            foreach (var mf in root.GetComponentsInChildren<MeshFilter>(true))
                if (mf.sharedMesh == source || (mf.sharedMesh != null && AssetDatabase.GetAssetPath(mf.sharedMesh) == fbx)) { lod0Filter = mf; break; }
            if (lod0Filter == null) return "SKIP " + prop + ": prefab has no mesh from " + fbx;

            MeshRenderer r0 = lod0Filter.GetComponent<MeshRenderer>();
            MeshRenderer r1 = CloneRenderer(lod0Filter, lod1, prop + "_LOD1");
            MeshRenderer r2 = CloneRenderer(lod0Filter, lod2, prop + "_LOD2");

            var group = root.AddComponent<LODGroup>();
            group.fadeMode = LODFadeMode.None;
            group.SetLODs(new[]
            {
                new LOD(Lod0Screen, new Renderer[] { r0 }),
                new LOD(Lod1Screen, new Renderer[] { r1 }),
                new LOD(CullScreen, new Renderer[] { r2 })
            });
            group.RecalculateBounds();
            PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
        }
        finally { PrefabUtility.UnloadPrefabContents(root); }

        return $"OK {prop}: {srcTris} -> LOD1 {TriangleCount(lod1)} / LOD2 {TriangleCount(lod2)} tris";
    }

    private static MeshRenderer CloneRenderer(MeshFilter original, Mesh mesh, string name)
    {
        GameObject clone = Object.Instantiate(original.gameObject, original.transform.parent);
        clone.name = name;
        clone.GetComponent<MeshFilter>().sharedMesh = mesh;
        return clone.GetComponent<MeshRenderer>();
    }

    private static Mesh Save(Mesh mesh, string name)
    {
        string path = OutFolder + "/" + name + ".asset";
        var existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
        if (existing != null) { EditorUtility.CopySerialized(mesh, existing); EditorUtility.SetDirty(existing); return existing; }
        AssetDatabase.CreateAsset(mesh, path);
        return mesh;
    }

    private static int TriangleCount(Mesh m)
    {
        long n = 0;
        for (int i = 0; i < m.subMeshCount; i++) n += m.GetIndexCount(i) / 3;
        return (int)n;
    }

    /// <summary>Vertex clustering on a grid sized by bisection to land near targetRatio of the source triangles.</summary>
    private static Mesh Simplify(Mesh src, float targetRatio, string name)
    {
        int target = Mathf.Max(32, Mathf.RoundToInt(TriangleCount(src) * targetRatio));
        float lo = 4f, hi = 512f;
        Mesh best = null;
        for (int iter = 0; iter < 14; iter++)
        {
            float cells = (lo + hi) * 0.5f;
            Mesh candidate = Cluster(src, cells, name);
            int tris = TriangleCount(candidate);
            if (best == null || Mathf.Abs(tris - target) < Mathf.Abs(TriangleCount(best) - target)) best = candidate;
            if (tris > target) hi = cells; else lo = cells;
        }
        return best;
    }

    private static Mesh Cluster(Mesh src, float cellsPerAxis, string name)
    {
        Vector3[] v = src.vertices, n = src.normals;
        Vector2[] uv = src.uv;
        Color[] col = src.colors;
        Bounds b = src.bounds;
        bool hasN = n != null && n.Length == v.Length, hasUv = uv != null && uv.Length == v.Length, hasCol = col != null && col.Length == v.Length;
        float cell = Mathf.Max(1e-7f, Mathf.Max(b.size.x, Mathf.Max(b.size.y, b.size.z)) / cellsPerAxis);

        var map = new Dictionary<(int, int, int, int, int), int>(v.Length);
        var remap = new int[v.Length];
        var sumP = new List<Vector3>(); var sumN = new List<Vector3>(); var sumC = new List<Color>(); var uvs = new List<Vector2>(); var count = new List<int>();
        for (int i = 0; i < v.Length; i++)
        {
            Vector3 p = v[i] - b.min;
            // UV cells keep texture seams from being welded together.
            var key = (Mathf.FloorToInt(p.x / cell), Mathf.FloorToInt(p.y / cell), Mathf.FloorToInt(p.z / cell),
                       hasUv ? Mathf.FloorToInt(uv[i].x * 24f) : 0, hasUv ? Mathf.FloorToInt(uv[i].y * 24f) : 0);
            if (!map.TryGetValue(key, out int idx))
            {
                idx = sumP.Count; map[key] = idx;
                sumP.Add(Vector3.zero); sumN.Add(Vector3.zero); sumC.Add(Color.clear); uvs.Add(hasUv ? uv[i] : Vector2.zero); count.Add(0);
            }
            remap[i] = idx;
            sumP[idx] += v[i]; if (hasN) sumN[idx] += n[i]; if (hasCol) sumC[idx] += col[i]; count[idx]++;
        }

        var verts = new Vector3[sumP.Count]; var norms = new Vector3[sumP.Count]; var cols = new Color[sumP.Count];
        for (int i = 0; i < verts.Length; i++)
        {
            verts[i] = sumP[i] / count[i];
            if (hasN) norms[i] = sumN[i].sqrMagnitude > 1e-12f ? sumN[i].normalized : Vector3.up;
            if (hasCol) cols[i] = sumC[i] / count[i];
        }

        var mesh = new Mesh { name = name };
        if (verts.Length > 65535) mesh.indexFormat = IndexFormat.UInt32;
        mesh.vertices = verts;
        if (hasN) mesh.normals = norms;
        if (hasUv) mesh.uv = uvs.ToArray();
        if (hasCol) mesh.colors = cols;
        mesh.subMeshCount = src.subMeshCount;
        for (int s = 0; s < src.subMeshCount; s++)
        {
            int[] tris = src.GetTriangles(s);
            var outTris = new List<int>(tris.Length);
            for (int i = 0; i < tris.Length; i += 3)
            {
                int a = remap[tris[i]], c = remap[tris[i + 1]], d = remap[tris[i + 2]];
                if (a == c || c == d || d == a) continue;
                outTris.Add(a); outTris.Add(c); outTris.Add(d);
            }
            mesh.SetTriangles(outTris, s, false);
        }
        if (!hasN) mesh.RecalculateNormals();
        mesh.RecalculateBounds();
        if (src.tangents != null && src.tangents.Length == v.Length && hasUv) mesh.RecalculateTangents();
        return mesh;
    }
}
